UserInvitations = {
    init: async function (app, container) {
		app = app || session.app;

        api.addToMetaCache([
            {
                "Name": "B2B",
                "Types": [
                    [meta[B2B/Company]]
                ]
            }
        ]);

		container = container || $(".component[name=UserInvitations]");
        await this.initCompaniesGrid(app, container);

        $('button[name=submitUserInvites]').on('click', await UserInvitations.sendUserInvites(app, container));
    },

    initCompaniesGrid: async function(app, container) {
        var gridContainer = $('[name=companiesGridContainer', container);

        var companiesDatasource = await model.getDatasource({
            endpoint: "B2B/Company",
            odataAppend: "?$filter=Buckets/any(b: startsWith(b/Bucket/Path, '" + app.Config.Deployment.TenantId + "/'))&$expand=Address,References,Buckets($expand=Bucket)",
            sort: { field: "Name", dir: "asc"}
        });

        var grid = new GridWidget(gridContainer, companiesDatasource);
        grid.selectable = true;
        grid.editable = false;
        grid.searchable = true;

        grid.search = {
            fields: ['Name']
        };

        grid.columns = [
		    { selectable: true, width: [theme[columns.checkbox]] },
            { field: "Name", title: "[resource_displayname[name]]" },
        ];

        await grid.init();
    },

    sendUserInvites: async function(app, container) {

    }
}
